    @Test("horizontal-layout-scale")
    func horizontalLayoutScale() async throws {
        let totalWidths: List<Double> = List<Double>()
        for scale in List<Double>(1.0, 2.0) {
            let settings: Settings = Settings()
            settings.display.layoutMode = LayoutMode.Horizontal
            settings.display.scale = scale
            settings.display.padding = List<Double>(0.0)
            let renderer: ScoreRenderer = try ScoreRenderer(settings)
            renderer.width = 1300.0
            try renderer.renderFinished.on({ (e: RenderFinishedEventArgs) in
                totalWidths.push(e.totalWidth)
            })
            try renderer.renderScore(ScoreLoader.loadAlphaTex("C4 D4 E4 F4 | C4 D4 E4 F4", settings), List<Double>(0.0))
        }
        TestGlobals.expect(totalWidths.length).toBe(2.0)
        TestGlobals.expect(totalWidths[1]).toBeCloseTo(totalWidths[0] * 2.0, 0.0)
    }

